package com.digitalhealth.controller;
import com.digitalhealth.dto.ConsentDTO;import com.digitalhealth.service.ConsentService;import com.digitalhealth.security.AccessService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/workers/{workerId}/consents") @CrossOrigin(originPatterns={"http://localhost:*","http://127.0.0.1:*"}) public class ConsentController{private final ConsentService service;private final AccessService access;public ConsentController(ConsentService x,AccessService a){service=x;access=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ConsentDTO grant(@PathVariable Long workerId,@Valid @RequestBody ConsentDTO d){access.workerOrAdmin(workerId);return service.grant(workerId,d);}@GetMapping public List<ConsentDTO> list(@PathVariable Long workerId){access.workerOrAdmin(workerId);return service.list(workerId);}@PatchMapping("/{id}/revoke") public ConsentDTO revoke(@PathVariable Long workerId,@PathVariable Long id){access.workerOrAdmin(workerId);return service.revoke(workerId,id);}}
